//! battclock.resource's functions: the clock that keeps the date while
//! the system is off or restarting - a clock chip on the board, or the
//! chip's own RTC timer. A resource: no Open or Close, its first function
//! in the first slot. The base comes from OpenResource("battclock.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/battclock_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const battclock = @import("../resources/battclock.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "battclock.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const ResetBattClock = libraries.lvo(0);
    pub const ReadBattClock = libraries.lvo(1);
    pub const WriteBattClock = libraries.lvo(2);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const ResetBattClock = *const fn (*BattClockBase) callconv(.c) void;
    pub const ReadBattClock = *const fn (*BattClockBase) callconv(.c) u32;
    pub const WriteBattClock = *const fn (*BattClockBase, u32) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const BattClockBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *BattClockBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Put the clock in working order and set it to 1 January 1978.
    pub fn ResetBattClock(self: *BattClockBase) void {
        return libraries.call(self, LVO.ResetBattClock, Fn.ResetBattClock, .{});
    }

    /// The seconds since 1 January 1978 the clock says; 0 for a clock that
    /// held no date, which is reset.
    pub fn ReadBattClock(self: *BattClockBase) u32 {
        return libraries.call(self, LVO.ReadBattClock, Fn.ReadBattClock, .{});
    }

    /// Set the clock to `seconds` since 1 January 1978.
    pub fn WriteBattClock(self: *BattClockBase, seconds: u32) void {
        return libraries.call(self, LVO.WriteBattClock, Fn.WriteBattClock, .{seconds});
    }
};
